import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  role: async (data: any) => {
    const role = data.role;
    if (role === "ANALYST" || role === "MANAGER" || role === "ADMIN") {
      return role;
    }
    return "ANALYST";
  },
});

import { HttpError } from "wasp/server";
import type { OnBeforeSignupHook } from "wasp/server/auth";

export const onBeforeSignup: OnBeforeSignupHook = async ({
  providerId,
  prisma,
  req,
}) => {
  const username = req.body?.username || providerId.providerUserId;
  const role = req.body?.role;

  if (role === "ADMIN") {
    if (!username || !username.endsWith("_admin")) {
      throw new HttpError(400, "Admin signup requires username to end with _admin");
    }
  }
};

import { HttpError } from "wasp/server";
import type { GetDocuments, GetAuditLogs } from "wasp/server/operations";

export const getDocuments: GetDocuments<void, any[]> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Document.findMany({
    orderBy: { id: "asc" },
  });
};

export const getAuditLogs: GetAuditLogs<void, any[]> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }
  return context.entities.AuditLog.findMany({
    orderBy: { timestamp: "desc" },
  });
};

import { HttpError } from "wasp/server";
import type { CreateDocument, UpdateDocument, DeleteDocument } from "wasp/server/operations";

export const createDocument: CreateDocument<
  { title: string; content: string },
  any
> = async ({ title, content }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }

  const doc = await context.entities.Document.create({
    data: {
      title,
      content,
      ownerId: context.user.id,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "CREATE",
      entityName: "Document",
      entityId: doc.id,
      userId: context.user.id,
      payload: JSON.stringify({ title, content }),
    },
  });

  return doc;
};

export const updateDocument: UpdateDocument<
  { id: number; title: string; content: string },
  any
> = async ({ id, title, content }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }

  const doc = await context.entities.Document.update({
    where: { id },
    data: {
      title,
      content,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "UPDATE",
      entityName: "Document",
      entityId: doc.id,
      userId: context.user.id,
      payload: JSON.stringify({ title, content }),
    },
  });

  return doc;
};

export const deleteDocument: DeleteDocument<{ id: number }, any> = async (
  { id },
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }

  await context.entities.Document.delete({
    where: { id },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "DELETE",
      entityName: "Document",
      entityId: id,
      userId: context.user.id,
      payload: JSON.stringify({ id }),
    },
  });

  return { success: true };
};

import { useState } from "react";
import { login } from "wasp/client/auth";
import { useNavigate, Link } from "react-router";

export function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await login({ username, password });
      navigate("/");
    } catch (err: any) {
      setError(err?.message || "An error occurred during login");
    }
  };

