          <div style={{ display: "grid", gap: "15px" }}>
            {documents.map((doc: any) => (
              <div key={doc.id} style={{ padding: "15px", border: "1px solid #eee", borderRadius: "6px" }}>
                <h3>{doc.title}</h3>
                <p>{doc.content}</p>
